import sys
import re


def extract(src_path, names, out_path):
    with open(src_path) as f:
        lines = f.readlines()

    out = [
        "// Auto-generated by scripts/extract_sim_models.py\n",
        "// Behavioral models for blackboxes used by netlist simulation.\n\n",
    ]
    i = 0
    found = set()
    while i < len(lines):
        m = re.match(r"\s*module\s+(\w+)\s*[\(#]", lines[i])
        if m and m.group(1) in names:
            name = m.group(1)
            found.add(name)
            out.append(lines[i])
            i += 1
            while i < len(lines):
                out.append(lines[i])
                if re.match(r"\s*endmodule", lines[i]):
                    out.append("\n")
                    i += 1
                    break
                i += 1
            continue
        i += 1

    missing = set(names) - found
    if missing:
        print("Warning: modules not found: %s" % ", ".join(sorted(missing)))
    with open(out_path, "w") as f:
        f.write("".join(out))


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 extract_sim_models.py input.sv output.sv")
        sys.exit(1)
    extract(
        sys.argv[1],
        [
            "ysyx_25020039_Pmem",
            "ysyx_25020039_Sim_Uart",
            "ysyx_25020039_PerfMonitor",
            "ysyx_25020039_SRAM",
            "ysyx_25020039_UART",
            "ysyx_25020039_Clint",
            "ysyx_25020039_Xbar",
        ],
        sys.argv[2],
    )
